import { useState, useEffect } from "react";
import { useParams, Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { motion } from "framer-motion";
import { CalendarDays, MapPin, Clock, Users, ArrowLeft, Target, BookOpen, UserCircle, Building2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Card, CardContent } from "@/components/ui/card";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import type { Tables } from "@/integrations/supabase/types";

type Event = Tables<"events">;
type Speaker = Tables<"event_speakers">;

const EVENT_TYPE_LABELS: Record<string, string> = {
  workshop: "Workshop", networking: "Networking", masterclass: "Masterclass",
  meetup: "Meetup", conference: "Conférence", webinar: "Webinaire",
};

const EventDetail = () => {
  const { id } = useParams();
  const [event, setEvent] = useState<Event | null>(null);
  const [speakers, setSpeakers] = useState<Speaker[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetch = async () => {
      if (!id) return;
      const [{ data: ev }, { data: sp }] = await Promise.all([
        supabase.from("events").select("*").eq("id", id).single(),
        supabase.from("event_speakers").select("*").eq("event_id", id),
      ]);
      setEvent(ev);
      setSpeakers(sp || []);
      setLoading(false);
    };
    fetch();
  }, [id]);

  if (loading) {
    return (
      <div className="min-h-screen bg-background">
        <Navbar />
        <div className="pt-24 pb-16 container mx-auto px-4 text-center text-muted-foreground">Chargement...</div>
      </div>
    );
  }

  if (!event) {
    return (
      <div className="min-h-screen bg-background">
        <Navbar />
        <div className="pt-24 pb-16 container mx-auto px-4 text-center">
          <p className="text-lg text-muted-foreground mb-4">Événement introuvable</p>
          <Link to="/events"><Button variant="outline"><ArrowLeft size={16} /> Retour</Button></Link>
        </div>
      </div>
    );
  }

  const spotsPercent = ((event.total_places - event.spots_left) / event.total_places) * 100;
  const isDeadlinePassed = event.registration_deadline && new Date(event.registration_deadline) < new Date();
  const isFull = event.spots_left === 0;

  const addToGoogleCalendar = () => {
    const start = `${event.date.replace(/-/g, "")}T${event.start_time.replace(/:/g, "")}00`;
    const end = event.end_time ? `${event.date.replace(/-/g, "")}T${event.end_time.replace(/:/g, "")}00` : start;
    const url = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(event.name)}&dates=${start}/${end}&location=${encodeURIComponent(event.address || event.location)}&details=${encodeURIComponent(event.description)}`;
    window.open(url, "_blank");
  };

  return (
    <div className="min-h-screen bg-background">
      <Navbar />

      {/* Hero */}
      <div className="relative pt-16">
        {event.cover_image_url ? (
          <div className="h-72 md:h-96 w-full overflow-hidden">
            <img src={event.cover_image_url} alt={event.name} className="w-full h-full object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-background/90 to-transparent" />
          </div>
        ) : (
          <div className="h-72 md:h-96 bg-gradient-to-br from-primary/20 to-primary/5" />
        )}
      </div>

      <div className="container mx-auto px-4 -mt-32 relative z-10 pb-16">
        <Link to="/events" className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground mb-4">
          <ArrowLeft size={16} /> Tous les événements
        </Link>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main content */}
          <div className="lg:col-span-2 space-y-8">
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
              <div className="flex flex-wrap gap-2 mb-4">
                <Badge>{EVENT_TYPE_LABELS[event.event_type]}</Badge>
                {event.difficulty && <Badge variant="outline">{event.difficulty}</Badge>}
                {event.is_recurring && <Badge variant="secondary">Récurrent</Badge>}
              </div>
              <h1 className="font-heading text-3xl md:text-4xl font-bold mb-4">{event.name}</h1>

              {/* Key info bar */}
              <div className="flex flex-wrap gap-4 text-sm text-muted-foreground mb-6 p-4 rounded-xl bg-muted/50">
                <div className="flex items-center gap-2">
                  <CalendarDays size={16} className="text-primary" />
                  {new Date(event.date).toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long", year: "numeric" })}
                </div>
                <div className="flex items-center gap-2">
                  <Clock size={16} className="text-primary" />
                  {event.start_time?.slice(0, 5)}{event.end_time ? ` - ${event.end_time.slice(0, 5)}` : ""}
                </div>
                <div className="flex items-center gap-2">
                  <MapPin size={16} className="text-primary" />
                  {event.location}
                </div>
                <div className="flex items-center gap-2">
                  <Users size={16} className="text-primary" />
                  {event.spots_left} places restantes
                </div>
              </div>

              {/* Description */}
              <div className="prose prose-sm max-w-none">
                <h2 className="font-heading text-xl font-bold mb-3">À propos de cet événement</h2>
                <p className="whitespace-pre-line text-muted-foreground">{event.description}</p>
              </div>
            </motion.div>

            {/* What you'll learn */}
            {event.what_you_learn && event.what_you_learn.length > 0 && (
              <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
                <h2 className="font-heading text-xl font-bold mb-4 flex items-center gap-2">
                  <BookOpen size={20} className="text-primary" /> Ce que vous apprendrez
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {event.what_you_learn.map((item, i) => (
                    <div key={i} className="flex items-start gap-3 p-3 rounded-lg bg-muted/50">
                      <span className="text-primary font-bold">✓</span>
                      <span className="text-sm">{item}</span>
                    </div>
                  ))}
                </div>
              </motion.div>
            )}

            {/* Programme */}
            {event.programme && (
              <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}>
                <h2 className="font-heading text-xl font-bold mb-3">Programme</h2>
                <p className="whitespace-pre-line text-muted-foreground text-sm">{event.programme}</p>
              </motion.div>
            )}

            {/* Speakers */}
            {speakers.length > 0 && (
              <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                <h2 className="font-heading text-xl font-bold mb-4 flex items-center gap-2">
                  <UserCircle size={20} className="text-primary" /> Intervenants
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {speakers.map((sp) => (
                    <Card key={sp.id}>
                      <CardContent className="p-4 flex items-center gap-4">
                        {sp.photo_url ? (
                          <img src={sp.photo_url} alt={sp.name} className="h-16 w-16 rounded-full object-cover" />
                        ) : (
                          <div className="h-16 w-16 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-lg">
                            {sp.name.charAt(0)}
                          </div>
                        )}
                        <div>
                          <p className="font-semibold">{sp.name}</p>
                          {sp.role_title && <p className="text-sm text-primary">{sp.role_title}</p>}
                          {sp.bio && <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{sp.bio}</p>}
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </motion.div>
            )}

            {/* Target audience */}
            {event.target_audience && event.target_audience.length > 0 && (
              <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.25 }}>
                <h2 className="font-heading text-xl font-bold mb-3 flex items-center gap-2">
                  <Target size={20} className="text-primary" /> Pour qui ?
                </h2>
                <div className="flex flex-wrap gap-2">
                  {event.target_audience.map((t, i) => (
                    <Badge key={i} variant="secondary" className="text-sm">{t}</Badge>
                  ))}
                </div>
              </motion.div>
            )}
          </div>

          {/* Sidebar */}
          <div className="lg:col-span-1">
            <Card className="sticky top-24">
              <CardContent className="p-6 space-y-5">
                {/* Price */}
                <div className="text-center">
                  {event.price_type === "free" ? (
                    <p className="text-3xl font-bold text-green-600">Gratuit</p>
                  ) : (
                    <div>
                      <p className="text-3xl font-bold">{event.price_amount}€</p>
                      {event.member_price && (
                        <p className="text-sm text-muted-foreground">Membres : {event.member_price}€</p>
                      )}
                    </div>
                  )}
                </div>

                {/* Spots */}
                <div>
                  <div className="flex justify-between text-sm mb-1">
                    <span>{event.total_places - event.spots_left} inscrits</span>
                    <span>{event.spots_left} restantes</span>
                  </div>
                  <Progress value={spotsPercent} className="h-3" />
                  {event.spots_left <= 5 && event.spots_left > 0 && (
                    <p className="text-sm text-destructive font-semibold mt-2 text-center">🔥 Plus que {event.spots_left} places !</p>
                  )}
                </div>

                {/* Deadline */}
                {event.registration_deadline && (
                  <p className="text-sm text-center text-muted-foreground">
                    Inscription avant le {new Date(event.registration_deadline).toLocaleDateString("fr-FR", { day: "numeric", month: "long" })}
                  </p>
                )}

                {/* CTA */}
                <Button
                  className="w-full text-lg py-6"
                  size="lg"
                  disabled={isFull || !!isDeadlinePassed}
                >
                  {isFull ? "Complet" : isDeadlinePassed ? "Inscriptions fermées" : event.cta_text}
                </Button>

                {/* Add to calendar */}
                <Button variant="outline" className="w-full" onClick={addToGoogleCalendar}>
                  📅 Ajouter au calendrier
                </Button>

                {/* Organizer */}
                <div className="pt-4 border-t border-border">
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <Building2 size={16} />
                    Organisé par <span className="font-medium text-foreground">{event.organizer_name}</span>
                  </div>
                </div>

                {/* Location */}
                {event.address && (
                  <div className="pt-4 border-t border-border">
                    <p className="text-sm font-medium mb-2 flex items-center gap-2"><MapPin size={16} className="text-primary" /> Lieu</p>
                    <p className="text-sm text-muted-foreground">{event.address}</p>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default EventDetail;
